interface Rule { lbp: number; nud?: (p: Parser) => Expr; led?: (p: Parser, l: Expr) => Expr }
const RULES = {
  "-": { lbp: 10, nud: p => neg(p.expr(70)), led: (p, l) => sub(l, p.expr(11)) },
  "+": { lbp: 10, led: (p, l) => add(l, p.expr(11)) },   // left-assoc: recurse at lbp + 1
  "*": { lbp: 20, led: (p, l) => mul(l, p.expr(21)) },
} satisfies Record<"+" | "-" | "*", Rule>;
function expr(minBp: number): Expr {
  let left = RULES[next().op].nud!(parser);               // null denotation
  while (minBp < (RULES[peek().op]?.lbp ?? 0))            // left denotation
    left = RULES[next().op].led!(parser, left);
  return left;
}
